// QueryNovels queries the novels edge of a User.
func (c *UserClient) QueryNovels(_m *User) *NovelQuery {
	query := (&NovelClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(user.Table, user.FieldID, id),
			sqlgraph.To(novel.Table, novel.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, user.NovelsTable, user.NovelsColumn),
		)
		schemaConfig := _m.schemaConfig
		step.To.Schema = schemaConfig.Novel
		step.Edge.Schema = schemaConfig.Novel
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

